package s2

import (
	"bytes"
	"encoding/binary"
	"reflect"
	"testing"
)

func encodeShapeIndex(t *testing.T, index *ShapeIndex) []byte {
	t.Helper()
	var buf bytes.Buffer
	if err := index.Encode(&buf); err != nil {
		t.Fatalf("Encode() failed: %v", err)
	}
	return buf.Bytes()
}

func roundTripShapeIndex(t *testing.T, index *ShapeIndex) *ShapeIndex {
	t.Helper()
	data := encodeShapeIndex(t, index)
	got := NewShapeIndex()
	if err := got.Decode(bytes.NewReader(data)); err != nil {
		t.Fatalf("Decode() failed: %v", err)
	}
	return got
}

// checkShapeIndexEqual verifies that two built indexes have identical shapes,
// IDs and cell contents.
func checkShapeIndexEqual(t *testing.T, want, got *ShapeIndex) {
	t.Helper()
	want.Build()
	if !got.IsFresh() {
		t.Errorf("decoded index is not fresh")
	}
	if got.nextID != want.nextID {
		t.Errorf("nextID = %d, want %d", got.nextID, want.nextID)
	}
	if got.Len() != want.Len() {
		t.Fatalf("Len() = %d, want %d", got.Len(), want.Len())
	}
	for id, ws := range want.shapes {
		gs := got.Shape(id)
		if gs == nil {
			t.Fatalf("shape %d missing after decode", id)
		}
		if reflect.TypeOf(gs) != reflect.TypeOf(ws) {
			t.Errorf("shape %d type = %T, want %T", id, gs, ws)
		}
		if gs.NumEdges() != ws.NumEdges() || gs.NumChains() != ws.NumChains() ||
			gs.Dimension() != ws.Dimension() || gs.ReferencePoint() != ws.ReferencePoint() {
			t.Errorf("shape %d properties differ", id)
		}
		for e := 0; e < ws.NumEdges(); e++ {
			if gs.Edge(e) != ws.Edge(e) {
				t.Errorf("shape %d edge %d = %v, want %v", id, e, gs.Edge(e), ws.Edge(e))
			}
		}
		for c := 0; c < ws.NumChains(); c++ {
			if gs.Chain(c) != ws.Chain(c) {
				t.Errorf("shape %d chain %d = %v, want %v", id, c, gs.Chain(c), ws.Chain(c))
			}
		}
	}
	if !reflect.DeepEqual(got.cells, want.cells) && !(len(got.cells) == 0 && len(want.cells) == 0) {
		t.Fatalf("cells = %v, want %v", got.cells, want.cells)
	}
	for _, id := range want.cells {
		wc, gc := want.cellMap[id], got.cellMap[id]
		if gc == nil || len(gc.shapes) != len(wc.shapes) {
			t.Fatalf("cell %v differs", id)
		}
		for i := range wc.shapes {
			w, g := wc.shapes[i], gc.shapes[i]
			if w.shapeID != g.shapeID || w.containsCenter != g.containsCenter ||
				!reflect.DeepEqual(append([]int{}, w.edges...), append([]int{}, g.edges...)) {
				t.Errorf("cell %v clipped shape %d = %+v, want %+v", id, i, g, w)
			}
		}
	}
}

func TestShapeIndexEncodeEmpty(t *testing.T) {
	index := NewShapeIndex()
	data := encodeShapeIndex(t, index)
	if len(data) == 0 {
		t.Fatalf("empty index encoded to zero bytes")
	}
	got := roundTripShapeIndex(t, index)
	checkShapeIndexEqual(t, index, got)
	if !got.Iterator().Done() {
		t.Errorf("decoded empty index has cells")
	}
}

func TestShapeIndexEncodeAllShapeTypes(t *testing.T) {
	index := NewShapeIndex()
	index.Add(makePolygon("0:0, 0:10, 10:10, 10:0; 2:2, 2:8, 8:8, 8:2", true))
	index.Add(makePolyline("20:20, 21:22, 23:25"))
	pv := PointVector(parsePoints("30:30 | 31:31 | -5:-5"))
	index.Add(&pv)
	index.Add(makeLaxPolyline("40:40, 41:41"))
	index.Add(makeLaxPolygon("50:50, 50:55, 55:55; 51:51, 51:52, 52:52"))
	index.Add(makeLoop("-20:-20, -20:-10, -10:-10, -10:-20"))
	index.Add(LaxLoopFromPoints(parsePoints("-40:-40, -40:-30, -30:-30")))
	index.Add(FullPolygon())
	index.Add(PolygonFromLoops(nil))
	index.Add(EmptyLoop())
	index.Add(FullLoop())

	// Encode without an explicit Build.
	got := roundTripShapeIndex(t, index)
	checkShapeIndexEqual(t, index, got)

	// Queries work on the decoded index.
	q := NewContainsPointQuery(got, VertexModelSemiOpen)
	p := PointFromLatLng(LatLngFromDegrees(1, 1))
	if want := NewContainsPointQuery(index, VertexModelSemiOpen).ContainingShapes(p); len(want) != len(q.ContainingShapes(p)) {
		t.Errorf("ContainingShapes differ after decode")
	}
	if !q.Contains(PointFromLatLng(LatLngFromDegrees(-15, -15))) {
		t.Errorf("decoded index should contain point in loop")
	}

	// The decoded index re-encodes to the same bytes.
	if a, b := encodeShapeIndex(t, index), encodeShapeIndex(t, got); !bytes.Equal(a, b) {
		t.Errorf("re-encoding decoded index produced different bytes")
	}
}

func TestShapeIndexEncodeZeroEdgeAndMixedChains(t *testing.T) {
	index := NewShapeIndex()
	empty := PointVector{}
	index.Add(&empty)
	index.Add(&Polyline{})
	index.Add(LaxPolylineFromPoints(nil))
	index.Add(LaxPolygonFromPoints(nil))
	index.Add(LaxLoopFromPoints(nil))
	index.Add(LaxPolygonFromPoints([][]Point{
		parsePoints("0:0, 0:1, 1:1"),
		{},
		parsePoints("5:5"),
		parsePoints("2:2, 2:3, 3:3, 3:2"),
	}))
	index.Add(LaxPolygonFromPoints([][]Point{parsePoints("10:10, 10:11, 11:11")}))
	index.Build()

	got := roundTripShapeIndex(t, index)
	checkShapeIndexEqual(t, index, got)
}

func TestShapeIndexEncodePreservesIDsAfterRemoval(t *testing.T) {
	index := NewShapeIndex()
	a := makePolyline("0:0, 1:1")
	b := makePolyline("2:2, 3:3")
	c := makePolyline("4:4, 5:5")
	index.Add(a)
	index.Add(b)
	index.Add(c)
	index.Build()
	index.Remove(b)
	index.Build()

	got := roundTripShapeIndex(t, index)
	checkShapeIndexEqual(t, index, got)
	if got.Shape(1) != nil || got.Shape(2) == nil {
		t.Errorf("shape IDs not preserved")
	}
}

func TestShapeIndexEncodeLarge(t *testing.T) {
	index := NewShapeIndex()
	index.Add(concentricLoopsPolygon(PointFromLatLng(LatLngFromDegrees(3, 4)), 10, 100))
	for i := 0; i < 20; i++ {
		index.Add(LaxPolylineFromPoints([]Point{randomPoint(), randomPoint(), randomPoint()}))
	}
	got := roundTripShapeIndex(t, index)
	checkShapeIndexEqual(t, index, got)
	quadraticValidate(t, got)
	testIteratorMethods(t, got)

	// The decoded index supports further incremental updates.
	got.Add(makePolyline("7:7, 8:8"))
	got.Build()
	quadraticValidate(t, got)
}

func TestShapeIndexDecodeMalformed(t *testing.T) {
	index := NewShapeIndex()
	index.Add(makePolygon("0:0, 0:10, 10:10, 10:0", true))
	index.Add(makePolyline("20:20, 21:22"))
	index.Add(makeLaxPolygon("50:50, 50:55, 55:55; 51:51, 51:52, 52:52"))
	data := encodeShapeIndex(t, index)

	if err := NewShapeIndex().Decode(bytes.NewReader(nil)); err == nil {
		t.Errorf("Decode(empty) succeeded")
	}
	for i := 0; i < len(data); i++ {
		if err := NewShapeIndex().Decode(bytes.NewReader(data[:i])); err == nil {
			t.Errorf("Decode(truncated to %d bytes) succeeded", i)
		}
	}
	// Corrupt each byte in turn; decoding must never panic.
	for i := 0; i < len(data); i++ {
		for _, x := range []byte{0xff, 0x80, 0x01} {
			c := append([]byte(nil), data...)
			c[i] ^= x
			_ = NewShapeIndex().Decode(bytes.NewReader(c))
		}
	}

	var huge [binary.MaxVarintLen64]byte
	n := binary.PutUvarint(huge[:], 1<<62)
	oversized := [][]byte{
		// Huge shape count.
		append([]byte{shapeIndexEncodingVersion, 10, 0x80, 0x80, 0x80, 0x80, 0x07}, huge[:n]...),
		// One polyline with a huge vertex count.
		append([]byte{shapeIndexEncodingVersion, 10, 1, 1, 0, byte(shapeKindPolyline)}, huge[:n]...),
		// One polyline with a large but allowed vertex count and no data.
		{shapeIndexEncodingVersion, 10, 1, 1, 0, byte(shapeKindPolyline), 0x80, 0x80, 0x80, 0x10},
		// Huge cell count.
		append([]byte{shapeIndexEncodingVersion, 10, 0, 0}, huge[:n]...),
		// Unknown version.
		{99},
	}
	for i, c := range oversized {
		if err := NewShapeIndex().Decode(bytes.NewReader(c)); err == nil {
			t.Errorf("Decode(oversized case %d) succeeded", i)
		}
	}

	// A failed decode leaves the destination unchanged.
	dst := NewShapeIndex()
	dst.Add(makePolyline("1:1, 2:2"))
	if err := dst.Decode(bytes.NewReader(data[:len(data)-1])); err == nil {
		t.Fatalf("Decode(truncated) succeeded")
	}
	if dst.Len() != 1 {
		t.Errorf("failed Decode modified the index")
	}
}

type unsupportedShape struct{ *edgeVectorShape }

func TestShapeIndexEncodeUnsupportedShape(t *testing.T) {
	index := NewShapeIndex()
	index.Add(&edgeVectorShape{})
	var buf bytes.Buffer
	if err := index.Encode(&buf); err == nil {
		t.Errorf("Encode with unsupported shape succeeded")
	}
}

